<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import SoulPet from './SoulPet.vue'
import Icon from './Icon.vue'
import {call,isDemo} from './service'
import {soulPages,soulCopy,guidedReply} from './soul'
const props=defineProps({member:Object,page:String,language:String,event:String,suspended:Boolean})
const emit=defineEmits(['navigate','tour'])
const dock=ref(null),position=ref(null),dragging=ref(false)
const open=ref(false),hidden=ref(false),paused=ref(localStorage.getItem('soul-motion')==='paused'),state=ref('idle'),look=ref(0),messages=ref([]),draft=ref(''),busy=ref(false),error=ref(''),ai=ref(false),consent=ref(false),available=ref(false),away=ref(false),composer=ref(null),log=ref(null),launcher=ref(null)
const copy=computed(()=>soulCopy[props.language]||soulCopy.en)
const hint=computed(()=>props.language==='ar'?'خطوة صغيرة نحو تعلم أفضل':soulPages[props.page]||'A little help is always close by.')
let reactionTimer,request=0,dragStart=null,suppressClick=false
const dockStyle=computed(()=>position.value?{left:position.value.x+'px',top:position.value.y+'px',right:'auto',bottom:'auto'}:{})
function clampPosition(){if(!position.value||!dock.value)return;const box=dock.value.getBoundingClientRect();position.value={x:Math.max(8,Math.min(position.value.x,document.documentElement.clientWidth-box.width-8)),y:Math.max(8,Math.min(position.value.y,innerHeight-box.height-8))}}
function rememberPosition(){if(position.value)localStorage.setItem('soul-position',JSON.stringify(position.value))}
function dragDown(event){if(event.button!==0||!event.isPrimary)return;const rect=dock.value.getBoundingClientRect();dragStart={id:event.pointerId,x:event.clientX,y:event.clientY,left:rect.left,top:rect.top};suppressClick=false;event.currentTarget.setPointerCapture(event.pointerId)}
function dragMove(event){if(!dragStart||dragStart.id!==event.pointerId)return;const dx=event.clientX-dragStart.x,dy=event.clientY-dragStart.y;if(Math.hypot(dx,dy)>6)dragging.value=true;if(dragging.value){position.value={x:dragStart.left+dx,y:dragStart.top+dy};clampPosition();state.value='greeting'}}
function dragEnd(event){if(!dragStart||dragStart.id!==event.pointerId)return;suppressClick=dragging.value;if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);dragStart=null;dragging.value=false;rememberPosition();react('idle')}
function petClick(){if(suppressClick){suppressClick=false;return}toggle()}
function keyboardMove(event){if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home'].includes(event.key))return;event.preventDefault();if(event.key==='Home'){position.value=null;localStorage.removeItem('soul-position');return}const r=dock.value.getBoundingClientRect(),step=event.shiftKey?30:10;position.value={x:r.left+(event.key==='ArrowRight'?step:event.key==='ArrowLeft'?-step:0),y:r.top+(event.key==='ArrowDown'?step:event.key==='ArrowUp'?-step:0)};clampPosition();rememberPosition()}
watch(open,async()=>{await nextTick();clampPosition()})
watch(hidden,async()=>{await nextTick();clampPosition()})
function react(value){clearTimeout(reactionTimer);state.value=value;reactionTimer=setTimeout(()=>state.value=busy.value?'thinking':'idle',2400)}
async function toggle(){open.value=!open.value;if(open.value){react('greeting');await nextTick();composer.value?.focus()}else launcher.value?.focus()}
function close(){open.value=false;launcher.value?.focus()}
function motion(){paused.value=!paused.value;localStorage.setItem('soul-motion',paused.value?'paused':'on')}
function clear(){request++;messages.value=[];draft.value='';error.value='';busy.value=false;state.value='idle';consent.value=false}
function navigate(route){emit('navigate',route);close()}
function visibility(){away.value=document.hidden}
async function scroll(){await nextTick();if(log.value)log.value.scrollTop=log.value.scrollHeight}
async function send(text=draft.value){
 if(busy.value||!text.trim())return
 if(text.length>1000){error.value='Keep your message within 1,000 characters.';return}
 if(ai.value&&!consent.value){error.value='Please review the OpenAI chat notice first.';return}
 const id=++request,history=messages.value.slice(-8).map(m=>({role:m.role,content:m.text}))
 messages.value.push({role:'user',text:text.trim()});draft.value='';error.value='';busy.value=true;state.value='thinking';scroll()
 try{
  let answer
  if(ai.value){const result=await call('chat',{message:text.trim(),history,page:props.page,language:props.language,consent:true},'soul');answer={text:result.reply}}
  else{answer=guidedReply(text,props.page);await new Promise(resolve=>setTimeout(resolve,450))}
  if(id!==request)return
  messages.value.push({role:'assistant',...answer});if(messages.value.length>40)messages.value.splice(0,messages.value.length-40);react('greeting')
 }catch(e){if(id===request){error.value=e.message;state.value='waiting'}}finally{if(id===request){busy.value=false;scroll()}}
}
watch(()=>props.page,()=>{if(!busy.value)react('review')})
watch(()=>props.event,value=>{if(value&&!busy.value)react(/saved|posted|recorded|complete|published|unlocked/i.test(value)?'celebrate':'waiting')})
watch(()=>props.suspended,value=>{if(value)open.value=false})
watch(ai,clear)
onMounted(async()=>{try{const p=JSON.parse(localStorage.getItem('soul-position'));if(Number.isFinite(p?.x)&&Number.isFinite(p?.y))position.value=p}catch{};await nextTick();clampPosition();window.addEventListener('resize',clampPosition);document.addEventListener('visibilitychange',visibility);visibility();if(!isDemo)try{available.value=(await call('status',{},'soul')).available}catch{/* Local guide stays available. */}})
onBeforeUnmount(()=>{window.removeEventListener('resize',clampPosition);request++;clearTimeout(reactionTimer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template><aside ref="dock" v-show="!suspended" class="soul-companion" :style="dockStyle" :class="{hidden,expanded:open,dragging}" aria-label="SOUL learning companion">
<button v-if="hidden" class="soul-restore" @click="hidden=false" aria-label="Show SOUL companion"><Icon name="Sprout" :size="18"/> SOUL</button>
<template v-else><section v-if="open" class="soul-chat" role="dialog" aria-modal="false" aria-labelledby="soul-title" @keydown.esc.stop="close">
<header><span class="soul-header-avatar"><SoulPet :state="state" :paused="paused||away"/></span><div><h2 id="soul-title">SOUL <span>✦</span></h2><small><i></i>{{ai?'OpenAI helper':copy.guide}}</small></div><button class="icon-button" aria-label="Clear SOUL conversation" title="Clear conversation" @click="clear"><Icon name="RotateCcw" :size="17"/></button><button class="icon-button" aria-label="Close SOUL chat" @click="close"><Icon name="X" :size="20"/></button></header>
<div class="soul-context"><Icon name="Sprout" :size="15"/><span>{{hint}}</span></div>
<div ref="log" class="soul-messages" role="log" aria-live="polite" aria-relevant="additions" :aria-busy="busy">
<div v-if="!messages.length" class="soul-welcome"><span class="soul-welcome-pet"><SoulPet state="greeting" :paused="paused||away"/></span><span class="eyebrow">{{copy.hello}}</span><h3>{{copy.intro}}</h3><p>{{copy.body}}</p><div class="soul-shortcuts"><button @click="navigate('classrooms')"><Icon name="BookOpen" :size="18"/>Find my classroom</button><button @click="navigate('schedule')"><Icon name="CalendarDays" :size="18"/>See my schedule</button><button @click="emit('tour');close()"><Icon name="Compass" :size="18"/>Show me around</button><button @click="send('I need a little break')"><Icon name="Leaf" :size="18"/>Take a little pause</button></div></div>
<article v-for="(message,i) in messages" :key="i" class="soul-message" :class="message.role"><small>{{message.role==='user'?'You':'SOUL'}}</small><p dir="auto">{{message.text}}</p><button v-if="message.route" class="text-button" @click="navigate(message.route)">{{message.label}} <Icon name="ArrowRight" :size="14"/></button></article><div v-if="busy" class="soul-thinking" role="status"><i></i><i></i><i></i><span>{{copy.thinking}}</span></div></div>
<div class="soul-chat-footer"><label v-if="available" class="soul-ai-switch"><input v-model="ai" type="checkbox">Use OpenAI chat</label><div v-if="ai&&!consent" class="soul-consent"><p>Your messages, recent chat, role, language and current page name will be sent to OpenAI. Keep personal details and passwords out of chat. Replies may be wrong.</p><label><input v-model="consent" type="checkbox">I understand and want to continue</label></div><p v-if="error" class="error" role="alert">{{error}}</p><form class="soul-compose" @submit.prevent="send()"><label class="sr-only" for="soul-message">Message SOUL</label><textarea id="soul-message" ref="composer" v-model="draft" rows="1" maxlength="1000" :placeholder="copy.placeholder" @keydown.enter.exact.prevent="send()"></textarea><button :disabled="busy||!draft.trim()||(ai&&!consent)" :aria-label="copy.send"><Icon name="ArrowUp" :size="19"/></button></form><small>{{ai?'AI helper · replies may be inaccurate':'Guided help · prepared answers · no AI request'}}<br>Chat clears when you reload or switch accounts.</small></div>
</section>
<span id="soul-move-help" class="sr-only">Click to chat. Drag to move. Use arrow keys to move, or Home to reset position.</span><div class="soul-dock"><div v-if="!open" class="soul-bubble"><strong>SOUL</strong><span>{{copy.hello}}</span></div><button ref="launcher" class="soul-launcher" :aria-label="open?'Close SOUL chat':copy.chat" :aria-expanded="open" aria-describedby="soul-move-help" @click="petClick" @pointerdown="dragDown" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="dragEnd" @keydown="keyboardMove" @mouseenter="react('greeting')" @mousemove="look=Math.max(-2,Math.min(2,($event.offsetX-45)/20))" @mouseleave="look=0"><SoulPet :state="state" :look="look" :paused="paused||away"/></button><div class="soul-controls"><button :aria-label="paused?'Resume SOUL animation':'Pause SOUL animation'" :title="paused?'Resume animation':'Pause animation'" @click="motion"><Icon :name="paused?'Play':'Pause'" :size="13"/></button><button aria-label="Hide SOUL companion" title="Hide SOUL" @click="hidden=true;close()"><Icon name="Minus" :size="13"/></button></div></div></template></aside></template>
<style>
.soul-companion{position:fixed;inset-inline-end:24px;bottom:18px;z-index:38;direction:inherit;max-width:calc(100vw - 28px)}.soul-dock{min-width:110px;display:flex;align-items:center;justify-content:flex-end;gap:5px;height:125px}.soul-launcher{touch-action:none;user-select:none;width:112px;height:118px;border:0;background:none;cursor:pointer;padding:0;filter:drop-shadow(0 5px 8px #68538520)}.soul-companion.dragging{cursor:grabbing;transition:none}.soul-companion.dragging .soul-launcher{cursor:grabbing;filter:drop-shadow(0 12px 10px #68538535);scale:1.04}.soul-launcher:hover{filter:drop-shadow(0 7px 13px #80639b35)}.soul-launcher:focus-visible{outline:3px solid #8270d0;border-radius:40px}.soul-bubble{background:#fffdfb;border:1px solid #e8e0ef;border-radius:16px 16px 3px 16px;padding:11px 15px;box-shadow:0 5px 25px #6451780d;margin-top:25px;max-width:180px}.soul-bubble strong{font-size:11px;color:#6e568e;display:block;letter-spacing:1.5px}.soul-bubble span{font-size:11px;color:#746b7d}.soul-controls{display:flex;position:absolute;bottom:0;inset-inline-end:28px;border:1px solid #e8dfef;background:#fff9;border-radius:20px;padding:2px}.soul-controls button{display:grid;place-items:center;background:none;border:0;color:#847591;width:24px;height:22px;border-radius:20px;cursor:pointer}.soul-controls button:hover{background:#e9e0f6}.soul-chat{width:384px;max-width:calc(100vw - 28px);height:min(600px,calc(100dvh - 154px));min-height:270px;border:1px solid #e4d8ef;border-radius:25px;background:#fffdfb;box-shadow:0 18px 70px #49336629;display:flex;flex-direction:column;overflow:hidden}.soul-chat>header{display:flex;align-items:center;gap:10px;padding:12px 17px;background:linear-gradient(115deg,#f2ebfc,#f9f6ef);border-bottom:1px solid #eee5f4}.soul-header-avatar{width:45px;height:48px}.soul-chat h2{font-size:18px;letter-spacing:2px;margin:0;color:#57406e}.soul-chat h2 span{color:#95b38d;font-size:13px}.soul-chat header>div{flex:1}.soul-chat header small{font-size:10px;color:#716577}.soul-chat header small i{display:inline-block;width:5px;height:5px;background:#89ab7c;border-radius:50%;margin-inline-end:5px}.soul-context{display:flex;gap:7px;align-items:center;padding:10px 18px;background:#faf7fc;color:#7e6c91;font-size:10px;line-height:1.6}.soul-messages{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:16px 20px;scrollbar-width:thin}.soul-welcome{text-align:center}.soul-welcome-pet{display:block;width:99px;height:104px;margin:0 auto 8px}.soul-welcome .eyebrow{font-size:8px;color:#827295;letter-spacing:1px}.soul-welcome h3{font-size:23px;margin:9px 0;color:#57426b}.soul-welcome p{font-size:12px;line-height:1.8;color:#86788c;max-width:260px;margin:0 auto 16px}.soul-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:8px}.soul-shortcuts button{display:flex;align-items:center;gap:9px;padding:11px 10px;text-align:start;font-size:10px;border:1px solid #e8e1ec;border-radius:12px;background:#fff;color:#766083;cursor:pointer}.soul-shortcuts button:hover{background:#f4effa;border-color:#b7a2cf}.soul-message{padding:11px 13px;border-radius:15px;background:#f3edf8;margin:0 18px 12px 0;color:#60516d;font-size:12px;line-height:1.75;overflow-wrap:anywhere}.soul-message.user{margin:0 0 12px 30px;background:#e9e1f5}.soul-message p{margin:4px 0;white-space:pre-wrap}.soul-message small{font-size:9px;font-weight:700;color:#897199}.soul-message .text-button{font-size:11px;margin-top:8px}.soul-chat-footer{padding:12px 16px 14px;border-top:1px solid #eee6f2}.soul-compose{display:flex;gap:6px;align-items:flex-end;background:#f8f4fc;border:1px solid #e7ddef;border-radius:16px;padding:7px}.soul-compose:focus-within{outline:2px solid #b49dcf;outline-offset:2px}.soul-compose textarea{flex:1;min-width:0;max-height:100px;resize:vertical;padding:8px 6px;background:none;border:0;outline:none;font:inherit;font-size:12px;color:#5c4a6c;line-height:1.6}.soul-compose>button{border:0;width:33px;height:33px;border-radius:11px;background:#8f75b4;color:#fff;cursor:pointer;display:grid;place-items:center}.soul-compose>button:disabled{opacity:.45;cursor:default}.soul-chat-footer>small{display:block;text-align:center;color:#8d7f94;font-size:8px;line-height:1.6;margin-top:8px}.soul-ai-switch,.soul-consent label{font-size:11px;display:flex;align-items:center;gap:7px;color:#705b82;margin-bottom:9px}.soul-consent{background:#f7f1e7;border-radius:10px;padding:10px;margin-bottom:10px;font-size:10px;line-height:1.6}.soul-consent p{margin:0 0 7px}.soul-thinking{display:flex;gap:4px;align-items:center;color:#8c7998;font-size:10px}.soul-thinking i{width:5px;height:5px;border-radius:50%;background:#b19acb;animation:soul-dot 1.3s infinite}.soul-thinking i:nth-child(2){animation-delay:.2s}.soul-thinking i:nth-child(3){animation-delay:.4s}.soul-thinking span{margin-inline-start:6px}.soul-restore{display:flex;gap:6px;align-items:center;padding:10px 14px;border:1px solid #e5daee;border-radius:25px;background:#fffdfb;color:#80628c;box-shadow:0 6px 20px #49336618;font-size:10px;cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@keyframes soul-dot{50%{opacity:.35;transform:translateY(-3px)}}@media(max-width:500px){.soul-companion{inset-inline-end:12px;bottom:max(10px,env(safe-area-inset-bottom))}.soul-dock{height:88px}.soul-launcher{width:80px;height:88px}.soul-controls{inset-inline-end:16px;bottom:-2px}.soul-bubble{display:none}.soul-chat{height:min(610px,calc(100dvh - 115px));width:calc(100vw - 24px);max-width:none;border-radius:22px}.soul-welcome-pet{width:80px;height:86px}.soul-welcome h3{font-size:21px}.soul-controls button{width:25px;height:24px}}@media(prefers-reduced-motion:reduce){.soul-thinking i{animation:none}}
</style>
